#!/bin/sh -ex
# alpine-fde install — guest-side plan (generated; runner=qemu)
# Host-side steps are comments; the CI harness executes them itself.
set -eux
# HOST: if mountpoint -q <TMP>/mnt 2>/dev/null || ls /dev/mapper/root[0-9]* >/dev/null 2>&1 || [ -e /dev/mapper/root-crypt ] || [ -e /dev/mapper/swap ] || ls /sys/fs/bcache/*/ >/dev/null 2>&1; then echo 'alpine-fde: info: reset: previous failed install detected — tearing down its stale target mounts + mapper mappings before re-partitioning'; fi || :
# HOST: if mountpoint -q <TMP>/mnt 2>/dev/null; then umount -R <TMP>/mnt && echo 'alpine-fde: info: reset: recursively unmounted stale target tree <TMP>/mnt' || echo 'alpine-fde: warn: reset: could not recursively unmount stale target tree <TMP>/mnt'; fi || :
# HOST: for m in /dev/mapper/root[0-9]* /dev/mapper/root-crypt /dev/mapper/swap; do [ -e "$m" ] || continue; cryptsetup close "${m#/dev/mapper/}" && echo "alpine-fde: info: reset: closed stale mapper $m" || echo "alpine-fde: warn: reset: could not close stale mapper $m"; done || :
# HOST: for d in /sys/fs/bcache/*/; do [ -f "${d}stop" ] || continue; u="${d%/}"; echo "${u##*/}" > "$u/stop" && echo "alpine-fde: info: reset: stopped live bcache set ${u##*/}" || echo "alpine-fde: warn: reset: could not stop bcache set ${u##*/}"; done || :
# HOST: if command -v modprobe >/dev/null 2>&1; then modprobe btrfs; fi # physical boot: the btrfs module is not auto-loaded
# HOST: if command -v mdev >/dev/null 2>&1; then mdev -s; fi # coldplug: settle /dev before partitioning
# HOST: printf 'label: gpt\nstart=2048, size=+512M, type=uefi, name="esp"\ntype=linux, name="root"\n' | sfdisk <TMP>/disk.img
# HOST: cryptsetup --batch-mode luksFormat --type luks2 --pbkdf argon2id --pbkdf-memory 1048576 --pbkdf-parallel 4 --iter-time 2000 --key-slot 2 --uuid <UUID> --key-file /dev/shm/alpine-fde-ephkey.<X> <TMP>/disk.img2 # keyslot 2: ephemeral install key (TEMPORARY keyslot — purged at first-boot finalization, §9.1 Stage 2; ADR-20); --batch-mode: NO interactive dangerous-action YES prompt (real-install defect 5)
# HOST: cryptsetup open --key-file /dev/shm/alpine-fde-ephkey.<X> <TMP>/disk.img2 root-crypt
# HOST: mkfs.btrfs -U <UUID> /dev/mapper/root-crypt
# HOST: mount /dev/mapper/root-crypt <TMP>/mnt
# HOST: btrfs subvolume create <TMP>/mnt/@
# HOST: btrfs subvolume create <TMP>/mnt/@home
# HOST: btrfs subvolume create <TMP>/mnt/@snapshots
# HOST: umount <TMP>/mnt
# HOST: mount -o subvol=@ /dev/mapper/root-crypt <TMP>/mnt && mkdir -p <TMP>/mnt/home <TMP>/mnt/.snapshots <TMP>/mnt/efi
# HOST: mount -o subvol=@home /dev/mapper/root-crypt <TMP>/mnt/home
# HOST: mount -o subvol=@snapshots /dev/mapper/root-crypt <TMP>/mnt/.snapshots
# HOST: mkfs.vfat -F 32 -n EFI <TMP>/disk.img1
# HOST: mount <TMP>/disk.img1 <TMP>/mnt/efi
printf '%s\n' 'https://dl-cdn.alpinelinux.org/alpine/v3.24/main' 'https://dl-cdn.alpinelinux.org/alpine/v3.24/community' >/etc/apk/repositories
# HOST: mkdir -p <TMP>/mnt/etc/apk && if [ -d /etc/apk/keys ]; then cp -a /etc/apk/keys <TMP>/mnt/etc/apk/ && echo 'alpine-fde: info: apk keyring seeded from the live env (apk verifies the mirror indexes against the target keyring)'; else echo 'alpine-fde: warn: no keyring on the live env (/etc/apk/keys) — apk will not trust any mirror'; fi || : # item 26 ext: seed the target keyring before the populate
# HOST: apk add --root <TMP>/mnt --initdb alpine-base
printf '%s\n' 'root UUID=<UUID> none luks,tpm2-device=auto,discard' >/etc/crypttab
printf '%s\n' 'UUID=<UUID> / btrfs subvol=@,defaults 0 1' 'UUID=<UUID> /home btrfs subvol=@home,defaults 0 2' 'UUID=<UUID> /.snapshots btrfs subvol=@snapshots,defaults 0 2' 'PARTUUID=<esp-partuuid> /efi vfat umask=0077 0 2' >/etc/fstab
printf '%s\n' 'auto lo' 'iface lo inet loopback' '' 'auto eth0' 'iface eth0 inet dhcp' >/etc/network/interfaces
printf '%s\n' 'root=UUID=<UUID> rootflags=subvol=@ ro console=ttyS0,115200 console=tty0 rd.shell=0 rd.emergency=poweroff' >/etc/alpine-fde/cmdline.txt
printf '%s\n' 'root=UUID=<UUID> rootflags=subvol=@ ro console=tty0 console=ttyS0,115200 rd.shell=0 rd.emergency=poweroff' >/etc/alpine-fde/cmdline-serial.txt
printf '%s\n' '# alpine-fde runtime config (KEY=VALUE).' '# Absent file or absent keys = built-in defaults: ROOT_FS=btrfs, BCACHE=0, TOPOLOGY=single.' 'ROOT_FS=btrfs' 'BCACHE=0' 'TOPOLOGY=single' 'ESP_PATH=/efi' >/etc/alpine-fde/alpine-fde.conf
# HOST: mkdir -p <TMP>/mnt/proc <TMP>/mnt/sys <TMP>/mnt/dev && mount -t proc proc <TMP>/mnt/proc && mount --bind /sys <TMP>/mnt/sys && mount --bind /dev <TMP>/mnt/dev
# HOST: mkdir -p <TMP>/mnt/dev/shm && mount --bind /dev/shm <TMP>/mnt/dev/shm
# HOST: mountpoint -q /sys/firmware/efi/efivars 2>/dev/null || mount -t efivarfs efivarfs /sys/firmware/efi/efivars 2>/dev/null || : # ensure the live env's efivarfs is mounted (NVRAM enrollment path)
# HOST: mkdir -p <TMP>/mnt/sys/firmware/efi/efivars && mount --bind /sys/firmware/efi/efivars <TMP>/mnt/sys/firmware/efi/efivars
# HOST: mkdir -p <TMP>/mnt/opt <TMP>/mnt/usr/local/bin <TMP>/mnt/opt/alpine-fde/bin <TMP>/mnt/opt/alpine-fde/lib <TMP>/mnt/opt/alpine-fde/hooks <TMP>/mnt/opt/alpine-fde/docs <TMP>/mnt/opt/alpine-fde/certs && cp -r <REPO>/bin/. <TMP>/mnt/opt/alpine-fde/bin/ && cp -r <REPO>/lib/. <TMP>/mnt/opt/alpine-fde/lib/ && cp -r <REPO>/hooks/. <TMP>/mnt/opt/alpine-fde/hooks/ && cp -r <REPO>/docs/. <TMP>/mnt/opt/alpine-fde/docs/ && cp -r <REPO>/certs/. <TMP>/mnt/opt/alpine-fde/certs/ && ln -sf /opt/alpine-fde/bin/alpine-fde <TMP>/mnt/usr/local/bin/alpine-fde
# HOST: mkdir -p <TMP>/mnt/etc/systemd/system && ln -sf /dev/null <TMP>/mnt/etc/systemd/system/systemd-boot-update.service
# HOST: if [ -f /etc/resolv.conf ]; then mkdir -p <TMP>/mnt/etc && cp /etc/resolv.conf <TMP>/mnt/etc/resolv.conf && echo 'alpine-fde: info: seeded target /etc/resolv.conf from the live env (in-chroot apk needs DNS)'; else echo 'alpine-fde: warn: live env has no /etc/resolv.conf — target DNS seed skipped (in-chroot apk may fail to resolve the mirror)'; fi || : # item 26b: seed the target resolver before the in-chroot transaction
# HOST: if [ -f /etc/hosts ]; then mkdir -p <TMP>/mnt/etc && cp /etc/hosts <TMP>/mnt/etc/hosts && echo 'alpine-fde: info: seeded target /etc/hosts from the live env (in-chroot apk resolves hosts-based mirror names)'; else echo 'alpine-fde: warn: live env has no /etc/hosts — target hosts seed skipped (in-chroot apk may fail to resolve a hosts-based mirror)'; fi || : # item 26b: seed the target hosts table before the in-chroot transaction
apk add --no-cache cryptsetup systemd-boot systemd-efistub ukify ukify-kernel-hook py3-pefile mkinitfs linux-lts tpm2-tools tpm2-tss-policy tpm2-tss-tcti-device sbsigntool efibootmgr openssl jq doas efitools openssh btrfs-progs
# HOST: f=<TMP>/mnt/etc/mkinitfs/mkinitfs.conf; grep -q alpine-fde "$f" 2>/dev/null || { mkdir -p <TMP>/mnt/etc/mkinitfs; [ -f "$f" ] && sed -i 's/^features="\(.*\)"$/features="\1 alpine-fde"/' "$f" || printf 'features="alpine-fde udev"\n' >"$f"; }; sed -n 's/^features="\(.*\)"$/\1/p' "$f" 2>/dev/null | grep -qw udev || sed -i 's/^features="\(.*\)"$/features="\1 udev"/' "$f"; grep -q '^custom_files=' "$f" 2>/dev/null || printf 'custom_files="/usr/share/alpine-fde/mkinitfs/alpine-fde-unseal.sh /usr/lib/udev/rules.d/69-bcache.rules /usr/lib/udev/rules.d/60-tpm.rules"\n' >>"$f" # §8.2/ADR-13: enable the alpine-fde + udev mkinitfs features (R640: no udev feature = no udevd in the initramfs — the udev rules never run, bcache registration + by-uuid starve) + register the non-ELF payload (hook script + udev rules) via custom_files (blocker #14, idempotent)
adduser -D -s /bin/ash admin && addgroup admin wheel
rc-update add networking boot
grep -q '^ttyS0:' /etc/inittab 2>/dev/null || printf '%s\n' '# alpine-fde: serial console getty (headless access — real-server blocker, Dell PowerEdge R640 2026-09-28)' 'ttyS0::respawn:/sbin/getty -L 115200 ttyS0 vt100' >>/etc/inittab # blocker: headless serial getty (idempotent guarded append)
grep -q 'alpine-fde: headless access' /etc/ssh/sshd_config 2>/dev/null || printf '%s\n' '' '# alpine-fde: headless access (real-server blocker, Dell PowerEdge R640 2026-09-28) — root SSH stays disabled; the ceremony account is the login path' 'PermitRootLogin no' 'PasswordAuthentication yes' >>/etc/ssh/sshd_config # blocker: sshd headless access (idempotent guarded append)
rc-update add sshd default
# HOST: inst_baseline_pending_write <TMP>/mnt
/opt/alpine-fde/bin/alpine-fde provision stage1 --mode in-chroot --keydir /etc/alpine-fde/keys --defer-custody
# HOST: rm -f /dev/shm/alpine-fde-enroll-deferred # stale deferred marker from a previous boot/install must not misroute the §9 verdict
export ALPINE_FDE_CMD_DIR=/opt/alpine-fde/lib/cmd; export ALPINE_FDE_ENROLL_DEFERRED_MARKER=/dev/shm/alpine-fde-enroll-deferred; . /opt/alpine-fde/lib/common.sh && . /opt/alpine-fde/lib/firmware.sh && fw_auth_enroll /sys/firmware/efi/efivars /etc/alpine-fde/keys /efi
ldr=''; for p in /usr/share/systemd/bootctl/systemd-bootx64.efi /usr/lib/systemd/boot/efi/systemd-bootx64.efi; do [ -f "$p" ] && { ldr="$p"; break; }; done; [ -n "$ldr" ] || { echo 'alpine-fde: ERROR: no systemd-boot loader EFI binary found in-chroot (probed /usr/share/systemd/bootctl/systemd-bootx64.efi, /usr/lib/systemd/boot/efi/systemd-bootx64.efi) — the systemd-boot package is missing or incomplete; the boot manager cannot be installed; fix the mirror/package set and re-run (completed steps skip via crash resume)' >&2; exit 1; }; mkdir -p /efi/EFI/systemd /efi/EFI/BOOT && sbsign --key /etc/alpine-fde/keys/release.pem --cert /etc/alpine-fde/keys/release.crt "$ldr" --output /efi/EFI/BOOT/BOOTX64.EFI && cp /efi/EFI/BOOT/BOOTX64.EFI /efi/EFI/systemd/systemd-bootx64.efi && echo "alpine-fde: info: boot manager RELEASE-SIGNED (blocker #26 addendum: the firmware verifies the FIRST loaded image — an unsigned BOOTX64.EFI dies before the UKI is ever reached) -> /efi/EFI/BOOT/BOOTX64.EFI + /efi/EFI/systemd/systemd-bootx64.efi (removable-media fallback path, no NVRAM dependency; §8.3)" # boot manager via guarded file copy of the systemd-boot loader binary (fail-closed probe; real-server blocker #7)
# HOST: mkdir -p <TMP>/mnt/etc/kernel-hooks.d <TMP>/mnt/etc/mkinitfs/features.d <TMP>/mnt/usr/share/alpine-fde/mkinitfs <TMP>/mnt/usr/lib/udev/rules.d <TMP>/mnt/etc/apk/triggers <TMP>/mnt/etc/conf.d <TMP>/mnt/etc/init.d <TMP>/mnt/etc/profile.d && cp <TMP>/hooks/kernel-hooks.d/alpine-fde-build.hook <TMP>/mnt/etc/kernel-hooks.d/alpine-fde-build.hook && cp <TMP>/hooks/kernel-hooks.d/alpine-fde-remove.hook <TMP>/mnt/etc/kernel-hooks.d/alpine-fde-remove.hook && cp <TMP>/hooks/mkinitfs/alpine-fde-unseal.sh <TMP>/mnt/usr/share/alpine-fde/mkinitfs/alpine-fde-unseal.sh && cp <TMP>/hooks/mkinitfs/features.d/alpine-fde.files <TMP>/mnt/etc/mkinitfs/features.d/alpine-fde.files && cp <TMP>/hooks/mkinitfs/features.d/alpine-fde.modules <TMP>/mnt/etc/mkinitfs/features.d/alpine-fde.modules && cp <TMP>/hooks/udev/60-tpm.rules <TMP>/mnt/usr/lib/udev/rules.d/60-tpm.rules && cp <TMP>/hooks/apk/triggers/alpine-fde.trigger <TMP>/mnt/etc/apk/triggers/alpine-fde.trigger && cp <TMP>/hooks/apk/triggers/alpine-fde-snapshot.trigger <TMP>/mnt/etc/apk/triggers/alpine-fde-snapshot.trigger && cp <TMP>/hooks/conf.d/alpine-fde-snapshot <TMP>/mnt/etc/conf.d/alpine-fde-snapshot && cp <TMP>/hooks/openrc/alpine-fde-finalize <TMP>/mnt/etc/init.d/alpine-fde-finalize && cp <TMP>/hooks/openrc/alpine-fde-audit <TMP>/mnt/etc/init.d/alpine-fde-audit && cp <TMP>/hooks/profile.d/alpine-fde.sh <TMP>/mnt/etc/profile.d/alpine-fde.sh && chmod +x <TMP>/mnt/etc/kernel-hooks.d/alpine-fde-build.hook <TMP>/mnt/etc/kernel-hooks.d/alpine-fde-remove.hook <TMP>/mnt/usr/share/alpine-fde/mkinitfs/alpine-fde-unseal.sh <TMP>/mnt/etc/apk/triggers/alpine-fde.trigger <TMP>/mnt/etc/apk/triggers/alpine-fde-snapshot.trigger <TMP>/mnt/etc/init.d/alpine-fde-finalize <TMP>/mnt/etc/init.d/alpine-fde-audit && find <TMP>/mnt/lib/modules/*/kernel -type f \( -name 'tpm.ko*' -o -name 'tpm_tis.ko*' -o -name 'tpm_crb.ko*' -o -name 'btrfs.ko*' -o -name 'bcache.ko*' \) 2>/dev/null | sed s:<TMP>/mnt/lib/modules/[^/]*/:: >> <TMP>/mnt/etc/mkinitfs/features.d/alpine-fde.modules; td=$(basename "$(readlink -f /sys/class/tpm/tpm0/device/driver 2>/dev/null)" 2>/dev/null); [ -n "$td" ] && info "install: detected TPM interface driver: $td (the staged feature files pack every found tpm/btrfs/bcache module, blocker #12/#14)"; :
rc-update add alpine-fde-finalize default
rc-update add alpine-fde-audit default
# HOST: inst_resolve_target_metadata <TMP>/disk.img1 <TMP>/mnt <UUID>
# HOST: inst_ceremony_recovery /dev/shm/alpine-fde-ephkey.<X> <TMP>/disk.img2 # §9.1 step 4 credential ceremony (1/3) — asked FIRST (item 12): LUKS2 recovery passphrase -> keyslot 0 of EVERY member CONTAINER via luksAddKey, authorized by the staged ephemeral install key. KDF pinned: Argon2id; §13 entropy floor enforced — re-prompt until met, confirm-typed
# HOST: inst_ceremony_user_password admin <TMP>/mnt # §9.1 step 4 credential ceremony (2/3): user account password (no-echo; press Enter to reuse the recovery passphrase — item 12 default-on-empty)
# HOST: inst_ceremony_release_key <TMP>/mnt/etc/alpine-fde/keys <TMP>/mnt/run/alpine-fde-release-pass # §9.1 step 4 credential ceremony (3/3): release.pem encrypted AES-256 PBKDF2 (keys_encrypt_release, ADR-18; press Enter to reuse the recovery passphrase — item 12), mode 0400; 2nd arg = the 0600 passphrase seam file IN THE TARGET ROOT (<mnt>/run/... — guest /run/...; blocker #8/#9)
export ALPINE_FDE_ROOT=/; export ALPINE_FDE_KEYDIR=/etc/alpine-fde/keys; [ -s /run/alpine-fde-release-pass ] && ALPINE_FDE_KEY_PASSPHRASE=$(cat /run/alpine-fde-release-pass) && rm -f /run/alpine-fde-release-pass && export ALPINE_FDE_KEY_PASSPHRASE; kv=$(cd /lib/modules 2>/dev/null && ls -1d */ 2>/dev/null | tr -d '/' | sort -V | tail -n 1); [ -n "$kv" ] || { echo 'alpine-fde: ERROR: no kernel module tree under /lib/modules — the linux-lts kernel package did not install into the target; fix the mirror/package set and re-run (completed steps skip via crash resume)' >&2; exit 1; }; /opt/alpine-fde/bin/alpine-fde kernel build "$kv" # §9.1 step 5 (SECRET-dependent — after the ceremony): signed boot manager + initial UKI (baseline pending ⇒ the build's ensure-once enrollment is state-gated OFF — the PROVISIONAL seal is the only Stage 1 enrollment); blocker #8/#9: keydir exported (keys_dir has no default) + passphrase from the in-target 0600 seam file (never argv); blocker #11: target kver derived in-guest (uname -r is the LIVE ISO kernel); blocker #12: ALPINE_FDE_ROOT=/ — in-chroot the TARGET IS /, and without it the initrd audit has no kernel-reality context (verdicts degrade to bare 'missing' instead of suffix-tolerant satisfaction)
# HOST: modprobe tpm_crb 2>/dev/null; modprobe tpm_tis 2>/dev/null; : # blocker #18 companion: ensure the live kernel's TPM driver is loaded (host-side; the in-chroot modprobe resolves the target's module tree)
export ALPINE_FDE_CMD_DIR=/opt/alpine-fde/lib/cmd; . /opt/alpine-fde/lib/common.sh && . /opt/alpine-fde/lib/seal.sh && require_pkgs objcopy:binutils && mkdir -p /run/alpine-fde && uki=$(ls /efi/EFI/Linux/alpine-fde-*.efi | head -n 1); objcopy -O binary --only-section=.pcrsig "$uki" /run/alpine-fde/pcrsig.json && for d in <TMP>/disk.img2; do seal_provisional /etc/alpine-fde/keys $d /run/alpine-fde/pcrsig.json /run/alpine-fde/token-${d##*/}.json $uki && token_add_keyslot $d "$SEAL_PASS_FILE" "$SEAL_SLOT" /dev/shm/alpine-fde-ephkey.<X> && token_import $d /run/alpine-fde/token-${d##*/}.json "$(token_next_id $d)" || exit 1; done && keys_scrub "$SEAL_PASS_FILE" && rm -rf /run/alpine-fde ${ALPINE_FDE_TMPDIR:-${TMPDIR:-/tmp}}/alpine-fde-seal.* # ADR-20 step 6: provisional Mechanism B seal (PCR 11) -> keyslot 1 on the CONTAINER dev (item 27); I1 seal-secret scrub
export ALPINE_FDE_CMD_DIR=/opt/alpine-fde/lib/cmd; . /opt/alpine-fde/lib/common.sh && . /opt/alpine-fde/lib/cmd/install.sh && require_pkgs efibootmgr:efibootmgr && inst_bootentry_ensure <TMP>/disk.img1 /efi $(cd /lib/modules 2>/dev/null && ls -1d */ 2>/dev/null | tr -d '/' | sort -V | tail -n 1) # task #27 + two-UKI design: the firmware NVRAM boot-entry PAIR ("Alpine FDE - <kver> (<date>)" -> \EFI\Linux\alpine-fde-<kver>.efi FIRST, "Alpine FDE - <kver> serial (<date>)" -> \EFI\Linux\alpine-fde-<kver>-serial.efi second; the firmware loads the UKIs directly, systemd-boot is only the removable fallback), HD(1,GPT,<esp-part-guid>), idempotent (family entries at dead GUIDs/stale loaders replaced; legacy single-UKI entries deleted)
# HOST: umount <TMP>/mnt/sys/firmware/efi/efivars 2>/dev/null || umount -l <TMP>/mnt/sys/firmware/efi/efivars 2>/dev/null || :; umount <TMP>/mnt/dev 2>/dev/null || umount -l <TMP>/mnt/dev 2>/dev/null || :; umount <TMP>/mnt/sys 2>/dev/null || umount -l <TMP>/mnt/sys 2>/dev/null || :; umount <TMP>/mnt/proc 2>/dev/null || umount -l <TMP>/mnt/proc 2>/dev/null || :; umount -R <TMP>/mnt 2>/dev/null || umount -l <TMP>/mnt 2>/dev/null || :; cryptsetup close root-crypt
# HOST: rm -f /dev/shm/alpine-fde-ephkey.<X> <TMP>/mnt/run/alpine-fde-release-pass # I1: ephemeral install key + release-passphrase seam file scrubbed (§9.1 teardown; blocker #8/#9)
# HOST: if [ -e /dev/shm/alpine-fde-enroll-deferred ]; then INST_SB_ENROLLED=0; INST_SB_DEFERRED=1; elif fw_var_present <TMP>/efivars PK; then INST_SB_ENROLLED=1; INST_SB_DEFERRED=0; else INST_SB_ENROLLED=0; INST_SB_DEFERRED=0; fi # enrollment verdict: deferred marker = a platform PK was already enrolled (factory or custom) — the release certificate import via the firmware UI is still pending; PK present = NVRAM enrollment succeeded; PK absent = enrollment refused — manual key import still pending (deferred)
# HOST: rm -f /dev/shm/alpine-fde-enroll-deferred # the verdict consumed the deferred marker (I1 seam hygiene)
# HOST: if [ "${INST_SB_DEFERRED:-}" = "1" ]; then printf '%s\n' 'alpine-fde: a platform key is ALREADY enrolled (factory or custom) — the installer made NO NVRAM writes; finish by importing the release certificate via the firmware UI:' '  1. the import-ready certificates are staged under /efi/alpine-fde-keys on the EFI System Partition: db.cer (the alpine-fde release certificate) plus the vendor option-ROM certificate (e.g. microsoft-option-rom-uefi-ca-2023.cer); otherwise copy the alpine-fde-keys directory to a FAT USB stick' '  2. reboot into the firmware setup (BIOS/UEFI) — this installer reboots there after your confirmation below' '  3. in the firmware key-management UI import db.cer AND the vendor certificate INTO THE EXISTING key database (db) — Secure Boot can stay ENABLED throughout' '  4. do NOT import KEK.cer or PK.cer and do NOT clear or replace the platform key — the existing PK and KEK stay (README.txt on the ESP and the marker file !import_all_auth_files repeat these steps — no need to memorize them)' '  5. while in firmware setup, set an administrator (supervisor) password' '  6. boot the installed system — completed install steps skip via crash resume; the first boot REFUSES to boot until db.cer is imported (that is the design, ADR-20)'; fi # deferred enrollment (platform PK present): UI import of db.cer + the vendor cert into the EXISTING db printed LAST
# HOST: if [ "${INST_SB_DEFERRED:-}" = "1" ]; then :; elif [ "${INST_SB_ENROLLED:-}" = "1" ]; then :; else printf '%s\n' 'alpine-fde: Secure Boot key material is staged under /efi/alpine-fde-keys on the EFI System Partition — the firmware refused NVRAM enrollment; finish the import manually:' '  1. import DIRECTLY from the internal ESP when the firmware key-management UI can browse it (the files to import are already at /efi/alpine-fde-keys — this is why they are staged on the EFI partition); otherwise copy the alpine-fde-keys directory to a FAT USB stick' '  2. reboot into the firmware setup (BIOS/UEFI) — this installer reboots there after your confirmation below' '  3. in the firmware key-management UI import the staged CERTIFICATES in this order (the firmware UI imports X.509 .cer files — it CANNOT import .auth packets): db.cer AND the vendor certificate (e.g. microsoft-option-rom-uefi-ca-2023.cer) for the Key Database, then KEK.cer (Key Exchange Key), then PK.cer (Platform Key — import LAST; it locks the key database)' '  4. the .auth packets staged alongside (db.auth kek.auth pk.auth) are for KeyTool.efi / efi-updatevar repair only; in the firmware file browser the marker file !import_all_auth_files and README.txt on the ESP repeat these steps — no need to memorize them' '  5. while in firmware setup, set an administrator (supervisor) password' '  6. boot the installed system — completed install steps skip via crash resume; the first boot REFUSES to boot until the keys are imported (that is the design, ADR-20)'; fi # deferred enrollment (firmware refused): manual-import instructions printed LAST (user directive: instructions at the very end; direct-from-ESP import first; the UI-importable .cer set db.cer + vendor cert + KEK.cer + PK.cer enumerated, the .auth packets named as repair-only; README.txt + marker enumerated)
